{
  "packet_id": "H6-T01-2",
  "claim_id": "C061",
  "status": "UNSUPPORTED",
  "claim": {
    "component_id": "C061.component",
    "value": "If agreed workload limits are exceeded, the trial must be stopped or reversed.",
    "scope": "Workload trigger for trial termination or reversal; the limits and response-selection rule are unspecified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P031",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The mapping explicitly prescribes stopping or reversing the trial when agreed workload limits are exceeded."
    }
  },
  "signal_basis": {
    "component_id": "C061.signal_basis",
    "value": "Under fixed test conditions and a common predeclared repetition rule, a reduced configuration repeatedly reproduces lateness while specified further removals cease to reproduce it; inconsistent or uncertain outcomes remain unresolved.",
    "scope": "Reduction tests of the selected reconstructed late case, rather than observations of workload during a field trial.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "CONTEXT"
        },
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans establish the selected-case scope, fixed conditions, repetition and uncertainty rules, and observed reduction pattern."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C061.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The verdict is not CONDITIONAL_WARRANT; no empirical bridging relation is asserted."
    }
  },
  "rationale": "The reduction signal supports test-relative reproduction of lateness. It does not establish the mandatory response to exceeding a trial's workload limits. P031 supplies that response as an explicit trial-management constraint, not as a conclusion warranted by the operation or signal. Even assuming workload limits are exceeded, the stopping-or-reversal requirement depends on accepting this prescribed rule.",
  "uncertainty": "This assessment concerns inferential warrant, not whether the explicitly authored workload safeguard is a reasonable policy.",
  "anomalies": []
}
